import {forestOverlay} from './forest-overlay.js';
import {BUSINESSES,businessType} from './businesses.js';
import {CITY_TILES} from './maps.js';
import {portrait} from './portraits.js';
import {GROUPS} from './content.js';
import {mapPoint,mapEdges,nextMapFocus,nearestMapTile} from './navigation.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class MiniMap{
 constructor(root,{jump,inspect,overview=()=>{}}){this.tiles=CITY_TILES;this.root=root;this.jump=jump;this.inspect=inspect;this.selected=0;this.followSelection=true;this.lastTurn='';const media=matchMedia('(min-width:1000px) and (min-height:650px)');this.expanded=media.matches;this.touched=false;
  const path=mapEdges(this.tiles).map(e=>`M${e.a.x},${e.a.y}L${e.b.x},${e.b.y}`).join(' ');
  root.innerHTML=`<button class="mini-toggle" aria-expanded="${this.expanded}" aria-controls="miniBody"><span>◈ 全岛地图</span><span class="mini-chevron">${this.expanded?'−':'+'}</span></button><div id="miniBody" ${this.expanded?'':'hidden'}><svg class="mini-svg" role="group" viewBox="0 0 360 250" aria-label="全岛路线，可用方向键选择地块，回车定位"><rect width="360" height="250" rx="14" fill="#b6cd9c"/><rect x="48" y="116" width="264" height="18" rx="8" fill="#81afb2"/><path d="${path}" stroke="#eee0b7" stroke-width="19" fill="none" stroke-linecap="round"/><path d="${path}" stroke="#738b7f" stroke-width="12" fill="none" stroke-linecap="round"/>${this.tiles.map(t=>{const p=mapPoint(t,this.tiles);return`<circle class="mini-node" data-mini-tile="${t.id}" cx="${p.x}" cy="${p.y}" r="${t.kind==='property'?5:7}" fill="${t.kind==='property'?GROUPS[t.group].color:'#fff0b7'}" stroke="#5b735b" stroke-width="1.4" role="button" tabindex="${t.id===0?0:-1}" aria-label="${t.id+1}. ${esc(t.name)}"><title>${esc(t.name)}</title></circle>`;}).join('')}<circle class="mini-selected" r="11" stroke="#fff6cd" stroke-width="2.5" fill="none" stroke-dasharray="4 3" pointer-events="none"/><g class="mini-pawns" pointer-events="none"></g></svg><div class="mini-footer"><span class="mini-name"></span><button class="mini-inspect">详情</button><button class="mini-enlarge" aria-label="放大全岛地图">放大</button></div><span class="sr-only">方向键选择地块，回车定位，详情查看价格与归属。</span></div>`;
  this.body=root.querySelector('#miniBody');this.toggle=root.querySelector('.mini-toggle');this.nodes=[...root.querySelectorAll('[data-mini-tile]')];this.marker=root.querySelector('.mini-selected');this.name=root.querySelector('.mini-name');this.toggle.addEventListener('click',()=>{this.touched=true;this.setExpanded(!this.expanded);});media.addEventListener('change',e=>{if(!this.touched)this.setExpanded(e.matches);});
  const choose=e=>{const node=e.target.closest('[data-mini-tile]');if(!node)return;this.select(+node.dataset.miniTile,false);this.jump(this.selected);};root.querySelector('svg').addEventListener('click',choose);
  root.querySelector('svg').addEventListener('keydown',e=>{const node=e.target.closest('[data-mini-tile]');if(!node)return;if(['Enter',' '].includes(e.key)){e.preventDefault();choose(e);return;}if(['Home','End','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();this.select(nextMapFocus(+node.dataset.miniTile,e.key,this.tiles),false);this.nodes[this.selected].focus();}});root.querySelector('.mini-inspect').addEventListener('click',()=>this.inspect(this.selected));root.querySelector('.mini-enlarge').addEventListener('click',()=>overview(this.selected));this.select(0,true);this.setExpanded(this.expanded);
 }
 setMap(tiles){this.tiles=tiles;const path=mapEdges(tiles).map(e=>`M${e.a.x},${e.a.y}L${e.b.x},${e.b.y}`).join(' ');for(const line of this.root.querySelectorAll('.mini-svg>path'))line.setAttribute('d',path);for(const t of tiles){const node=this.nodes[t.id],p=mapPoint(t,tiles);node.setAttribute('cx',p.x);node.setAttribute('cy',p.y);node.setAttribute('r',t.kind==='property'?5:7);node.querySelector('title').textContent=t.name;node.setAttribute('fill',t.kind==='property'?GROUPS[t.group].color:'#fff0b7');node.setAttribute('aria-label',`${t.id+1}. ${t.name}`);}this.lastTurn='';}
 setExpanded(value){this.expanded=value;this.toggle.setAttribute('aria-expanded',String(value));this.toggle.querySelector('.mini-chevron').textContent=value?'−':'+';this.body.hidden=!value;this.root.classList.toggle('is-collapsed',!value);}
 select(id,follow=false){if(!this.tiles[id])return;this.selected=id;this.followSelection=follow;for(const node of this.nodes)node.setAttribute('tabindex',+node.dataset.miniTile===id?'0':'-1');const p=mapPoint(this.tiles[id],this.tiles);this.marker.setAttribute('cx',p.x);this.marker.setAttribute('cy',p.y);this.name.textContent=this.labels?.[id]||`${id+1}. ${this.tiles[id].name}`;}
 sync(game,{visible=true}={}){if(this.tiles!==game.tiles)this.setMap(game.tiles);this.root.hidden=!visible;if(!visible)return;const s=game.s,turn=`${s.round}:${s.current}`;if(turn!==this.lastTurn){this.lastTurn=turn;this.followSelection=true;}this.labels=[];if(this.followSelection)this.select(game.player.pos,true);for(const t of this.tiles){const node=this.nodes[t.id],o=s.ownership[t.id];node.setAttribute('fill',o?game.char(s.players[o.player]).estateColor:t.kind==='property'?GROUPS[t.group].color:'#fff0b7');node.setAttribute('stroke-width',o?'3':'1.4');const label=`${t.id+1}. ${t.name}${o?' · '+game.char(s.players[o.player]).name+' · '+(o.level?BUSINESSES[businessType(o)].name+' '+o.level+'级':'待建空地'):''}`;this.labels[t.id]=label;node.setAttribute('aria-label',label);node.querySelector('title').textContent=label;}
  this.name.textContent=this.labels[this.selected];const pawns=mapPawnMarkers(game).map(({player:p,x,y})=>{const color=game.char(p).estateColor;return`<circle cx="${x}" cy="${y}" r="${p.id===s.current?6:4.5}" fill="${color}" stroke="${p.id===s.current?'#fffbe2':'#644727'}" stroke-width="${p.id===s.current?3:2}"/>`;}).join('');this.root.querySelector('.mini-pawns').innerHTML=pawns+forestOverlay(game);
 }
}

const facilities={start:['⚑','起点'],bank:['￥','银行'],stock:['↗','股票'],hospital:['✚','医院'],shop:['◆','商店'],spirit:['✦','神殿'],event:['?','事件'],rest:['☾','休养'],tax:['−','清洁']};
export function mapPawnMarkers(game){return game.s.players.filter(p=>p.alive).map(player=>{const p=mapPoint(game.tiles[player.pos],game.tiles),peers=game.s.players.filter(q=>q.alive&&q.pos===player.pos),span=(peers.length-1)*9/2,center=Math.max(8+span,Math.min(352-span,p.x));return {player,x:center+(peers.indexOf(player)-(peers.length-1)/2)*9,y:Math.max(8,p.y-12),tileX:p.x,tileY:p.y};});}
export function mapTileInfo(game,id){
 const t=game.tiles[id],o=game.s.ownership[id],owner=o?game.char(game.s.players[o.player]):null;
 const description=owner?`${owner.name} · ${o.level?BUSINESSES[businessType(o)].name+' '+o.level+'级':'待建空地'}`:t.kind==='property'?`空地 · ${t.price} 奶币`:facilities[t.kind]?.[1]||'公共设施';
 return {name:t.name,description,label:`${id+1}. ${t.name} · ${description}`,color:owner?.estateColor||(t.kind==='property'?'#f6e8bd':'#577d70'),glyph:t.kind==='property'?(o?.level?String(o.level):''):facilities[t.kind]?.[0]||'·',vacant:t.kind==='property'&&!o};
}
export class MapOverview{
 constructor(root,game,{selected=game.player.pos,inspect=()=>{}}={}){
  this.root=root;this.game=game;this.tiles=game.tiles;const tiles=game.tiles,path=mapEdges(tiles).map(e=>`M${e.a.x},${e.a.y}L${e.b.x},${e.b.y}`).join(' ');
  root.innerHTML=`<p class="overview-hint">点选地块看归属与用途，再点详情。打开地图期间，对局等待。</p><svg class="overview-svg" viewBox="0 0 360 250" role="group" aria-label="全岛大地图，方向键选择地块，回车查看详情"><rect width="360" height="250" rx="12" fill="#b5cfa4"/><path d="M40 131 Q180 102 320 128" stroke="#85b5b6" stroke-width="12" fill="none"/><path d="${path}" stroke="#f5e7c2" stroke-width="21" fill="none" stroke-linecap="round"/><path d="${path}" stroke="#7c9587" stroke-width="13" fill="none" stroke-linecap="round"/>${tiles.map(t=>{const p=mapPoint(t,tiles),d=mapTileInfo(game,t.id);return `<circle data-overview-tile="${t.id}" cx="${p.x}" cy="${p.y}" r="8" fill="${d.color}" stroke="#5f704c" stroke-width="1.2" ${d.vacant?'stroke-dasharray="2 2"':''} tabindex="-1" role="button" aria-label="${esc(d.label)}"><title>${esc(d.label)}</title></circle><text class="overview-symbol" x="${p.x}" y="${p.y+3}" fill="${t.kind==='property'?'#583f22':'#fff5d5'}">${d.glyph}</text>`;}).join('')}<g class="overview-positions" pointer-events="none">${forestOverlay(game)}${mapPawnMarkers(game).map(({player:p,x,y,tileX,tileY})=>{const c=game.char(p);return `<g><path d="M${tileX},${tileY}L${x},${y}" stroke="${c.estateColor}" stroke-width="1"/><circle cx="${x}" cy="${y}" r="6" fill="${c.estateColor}" stroke="${p.id===game.s.current?'#fff9d5':'#5d4b2c'}" stroke-width="${p.id===game.s.current?2.5:1}"/><text x="${x}" y="${y+2}" class="overview-pawn-number">${p.id+1}</text></g>`;}).join('')}</g><circle class="overview-selected" r="12" fill="none" stroke="#fff5ce" stroke-width="2.5" pointer-events="none"/></svg><div class="overview-selection" aria-live="polite"><div><strong></strong><span></span></div><button class="secondary overview-inspect">地块详情 ↗</button></div><div class="overview-roster">${game.s.players.map(p=>{const c=game.char(p);return `<button class="overview-player${p.alive?'':' eliminated'}" data-overview-player="${p.id}" style="--owner-color:${c.estateColor}" aria-label="定位${c.name}${p.alive?'':'，已退出'}" ${p.alive?'':'disabled'}><span class="overview-face">${portrait(c.id)}</span><span><b>${p.id+1} · ${c.name}</b><small>${p.id===game.s.current?'当前回合':p.human?'你':p.alive?'电脑':'已退出'}</small></span></button>`;}).join('')}</div><div class="overview-key">${Object.values(facilities).map(([glyph,name])=>`<span><i>${glyph}</i>${name}</span>`).join('')}<span><i class="overview-vacant"></i>待售空地</span><span>地块数字＝建筑等级</span></div>`;
  this.svg=root.querySelector('svg');this.nodes=[...root.querySelectorAll('[data-overview-tile]')];this.marker=root.querySelector('.overview-selected');this.select(selected);
  this.svg.addEventListener('click',e=>{const matrix=this.svg.getScreenCTM();if(!matrix)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()),id=nearestMapTile(p.x,p.y,tiles);if(id!==null)this.select(id);});
  this.svg.addEventListener('keydown',e=>{if(!e.target.matches('[data-overview-tile]'))return;if(['Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();inspect(this.selected);}else if(['Home','End','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();e.stopPropagation();this.select(nextMapFocus(this.selected,e.key,this.tiles));this.nodes[this.selected].focus({preventScroll:true});}});
  root.querySelector('.overview-inspect').addEventListener('click',()=>inspect(this.selected));for(const b of root.querySelectorAll('[data-overview-player]'))b.addEventListener('click',()=>this.select(game.s.players[+b.dataset.overviewPlayer].pos));
 }
 select(id){if(!this.game.tiles[id])return;this.selected=id;const p=mapPoint(this.game.tiles[id],this.game.tiles),d=mapTileInfo(this.game,id);this.marker.setAttribute('cx',p.x);this.marker.setAttribute('cy',p.y);for(const node of this.nodes)node.setAttribute('tabindex',+node.dataset.overviewTile===id?'0':'-1');this.root.querySelector('.overview-selection strong').textContent=`${id+1}. ${d.name}`;this.root.querySelector('.overview-selection span').textContent=d.description;}
}
